<?php
class DashboardController {public function index():void{Auth::require();$id=company_id();$stats=['products'=>db_one('SELECT COUNT(*) n FROM products WHERE company_id=?',[$id])['n']??0,'customers'=>db_one('SELECT COUNT(*) n FROM customers WHERE company_id=?',[$id])['n']??0,'sales'=>db_one('SELECT COALESCE(SUM(total),0) n FROM sales WHERE company_id=? AND MONTH(created_at)=MONTH(CURRENT_DATE()) AND YEAR(created_at)=YEAR(CURRENT_DATE())',[$id])['n']??0,'expenses'=>db_one('SELECT COALESCE(SUM(amount),0) n FROM expenses WHERE company_id=? AND MONTH(expense_date)=MONTH(CURRENT_DATE()) AND YEAR(expense_date)=YEAR(CURRENT_DATE())',[$id])['n']??0];$recent=db_all('SELECT s.*,c.name customer FROM sales s LEFT JOIN customers c ON c.id=s.customer_id WHERE s.company_id=? ORDER BY s.id DESC LIMIT 6',[$id]);View::render('dashboard/index',compact('stats','recent'));}}
